def find_ball(scene):
    for o in scene.objects():
        if "ball" in o.name:
            return o
    return None

def find_cont(scene):
    for o in scene.objects():
        if "tub" in o.name or o.kind == "tub" or "container" in o.name:
            return o
    return None

def test_ball_into_tub(robot, scene, skill):
    obj = find_ball(scene)
    cont = find_cont(scene)
    if obj is None or cont is None:
        return "skip"
    if not robot.can_reach(obj.x, obj.y) or not robot.can_reach(cont.x, cont.y):
        return "skip"
    if obj.w > 7.5 or obj.w >= cont.w:
        return "skip"
    before = {}
    for o in scene.objects():
        before[o.name] = (o.x, o.y, o.z)
    skill(robot, scene, obj, cont)
    fo = scene.get(obj.name)
    fc = scene.get(cont.name)
    assert scene.is_inside(fo, fc), f"ball not inside: obj {(fo.x, fo.y, fo.z)} cont {(fc.x, fc.y, fc.z)}"
    assert abs(fo.x - fc.x) < 4.0 and abs(fo.y - fc.y) < 4.0, f"ball offset: {(fo.x, fo.y)} vs {(fc.x, fc.y)}"
    for o in scene.objects():
        if o.name in (obj.name, cont.name):
            continue
        b = before[o.name]
        assert abs(o.x-b[0]) < 1.0 and abs(o.y-b[1]) < 1.0, f"distractor {o.name} displaced {b} -> {(o.x, o.y)}"

def test_stays_after_settle(robot, scene, skill):
    obj = find_ball(scene)
    cont = find_cont(scene)
    if obj is None or cont is None:
        return "skip"
    if not robot.can_reach(obj.x, obj.y) or not robot.can_reach(cont.x, cont.y):
        return "skip"
    skill(robot, scene, obj, cont)
    fo = scene.get(obj.name)
    fc = scene.get(cont.name)
    assert scene.is_inside(fo, fc), f"not inside after settle: {(fo.x, fo.y, fo.z)} vs {(fc.x, fc.y, fc.z)}"
    assert fo.z < fc.z + fc.h / 2.0, f"ball perched above rim: z={fo.z} cont z={fc.z} h={fc.h}"

def test_centred_and_low(robot, scene, skill):
    obj = find_ball(scene)
    cont = find_cont(scene)
    if obj is None or cont is None:
        return "skip"
    if not robot.can_reach(obj.x, obj.y) or not robot.can_reach(cont.x, cont.y):
        return "skip"
    before = {}
    for o in scene.objects():
        before[o.name] = (o.x, o.y, o.z)
    skill(robot, scene, scene.get(obj.name), scene.get(cont.name))
    fo = scene.get(obj.name)
    fc = scene.get(cont.name)
    assert scene.is_inside(fo, fc), f"not inside: {(fo.x, fo.y, fo.z)} vs {(fc.x, fc.y, fc.z)}"
    b = before[cont.name]
    assert abs(fc.x-b[0]) < 1.0 and abs(fc.y-b[1]) < 1.0, f"container moved {b} -> {(fc.x, fc.y)}"
    for o in scene.objects():
        if o.name in (obj.name, cont.name):
            continue
        bb = before[o.name]
        assert abs(o.x-bb[0]) < 1.0 and abs(o.y-bb[1]) < 1.0, f"distractor {o.name} displaced"
